const CACHE_NAME = 'kids-star-rewards-v4';

const APP_FILES = [
  '/',
  '/manifest.webmanifest',
  '/icon-192.png',
  '/icon-512.png',
  '/apple-touch-icon.png',
  '/favicon.svg'
];

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);

    // Save the main app page.
    const response = await fetch('/', { cache: 'reload' });

    if (!response.ok) {
      throw new Error('Could not load the app page');
    }

    await cache.put('/', response.clone());

    // Find the JavaScript and CSS files generated by Vite.
    const html = await response.text();
    const assets = Array.from(
    html.matchAll(/\b(?:src|href)="([^"]+)"/g),
      match => match[1]
    ).filter(path => path.startsWith('/'));

    const files = [...new Set([...APP_FILES, ...assets])];

    // Save app files for offline use.
    await Promise.all(files.map(async path => {
      try {
        const file = await fetch(path, { cache: 'reload' });
        if (file.ok) {
          await cache.put(path, file);
        }
      } catch {
        console.log('Could not cache:', path);
      }
    }));

    await self.skipWaiting();
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const keys = await caches.keys();

    await Promise.all(
      keys
        .filter(key =>
          key.startsWith('kids-star-rewards-') &&
          key !== CACHE_NAME
        )
        .map(key => caches.delete(key))
    );

    await self.clients.claim();
  })());
});

self.addEventListener('fetch', event => {
  const request = event.request;

  if (request.method !== 'GET') return;

  const url = new URL(request.url);

  if (url.origin !== self.location.origin) return;
  if (url.pathname === '/sw.js') return;

  // Always try the latest app page first.
  if (request.mode === 'navigate') {
    event.respondWith((async () => {
      try {
        const response = await fetch(request);
        if (response.ok) {
          const cache = await caches.open(CACHE_NAME);
          await cache.put('/', response.clone());
        }
        return response;
      } catch {
        return (
          await caches.match(request) ||
          await caches.match('/') ||
          Response.error()
        );
      }
    })());
    return;
  }

  // Load saved app files from cache first.
  const isAppFile =
    url.pathname.startsWith('/assets/') ||
    ['script', 'style', 'image', 'font'].includes(request.destination) ||
    APP_FILES.includes(url.pathname);

  if (isAppFile) {
    event.respondWith((async () => {
      const cached = await caches.match(request);
      if (cached) return cached;

      const response = await fetch(request);

      if (response.ok) {
        const cache = await caches.open(CACHE_NAME);
        await cache.put(request, response.clone());
      }

      return response;
    })());
  }
});
